import sys
from collections import defaultdict
from math import sqrt

def prime_factors(n):
    factors = defaultdict(int)
    d = 2
    while d <= int(sqrt(n)):
        while (n % d) == 0:
            factors[d] += 1
            n //= d
        d += 1
    if n > 1:
        factors[n] += 1
    return factors

def merge_factors(factors_list):
    merged_factors = defaultdict(int)
    for factors in factors_list:
        for prime, count in factors.items():
            merged_factors[prime] = max(merged_factors[prime], count)
    return merged_factors

def count_vertices(factors):
    return sum(factors.values())

def min_divisor_tree_vertices(numbers):
    if not numbers:
        return 0
    if len(numbers) == 1:
        return 1

    factors_list = [prime_factors(num) for num in numbers]
    merged_factors = merge_factors(factors_list)

    total_vertices = 0
    for prime, count in merged_factors.items():
        total_vertices += count

    return total_vertices + (len(numbers) - 1)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    numbers = list(map(int, input[1:n+1]))
    print(min_divisor_tree_vertices(numbers))

if __name__ == "__main__":
    main()
